package aippatch

import (
	"context"
	"sync/atomic"

	"github.com/jackc/pgx/v5"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/known/fieldmaskpb"
)

// Mapping is the static description of how a proto message round-trips
// through a SQL table. Generated by aippatchgen; never hand-edited.
type Mapping[T proto.Message] struct {
	// Table is the SQL table name.
	Table string
	// PK is the primary-key column name used in the WHERE clause.
	PK string
	// SoftDelete is an optional column name. When non-empty, Apply adds
	// "soft_delete IS NULL" to the WHERE clause so soft-deleted rows are
	// treated as NotFound.
	SoftDelete string
	// EmptyMask controls what happens when Op.Mask has zero paths.
	EmptyMask EmptyMaskPolicy
	// Bindings is the ordered list of proto-field-to-column mappings.
	Bindings []Binding
	// AutoSet holds SQL expressions appended unconditionally to the SET clause.
	AutoSet []AutoSetClause

	// Populated by Validate(); unexported.
	bindingsByProto  map[string]*Binding
	bindingsByColumn map[string]*Binding
	codecs           map[string]EnumCodec
	validated        atomic.Bool
}

// Binding pairs one proto field with one SQL column.
type Binding struct {
	// Proto is the proto field name (snake_case, e.g. "display_name").
	Proto string
	// Column is the SQL column name (may differ from Proto via overrides).
	Column string
	// SQLType is the normalized SQL type string (e.g. "text", "uuid", "timestamptz").
	SQLType string
	// Writable is true if this field may appear in an update_mask path.
	Writable bool
	// Codec is "" for scalars, "timestamp" for Timestamp fields, or
	// "enum:<name>" for enum fields referencing a named EnumCodec.
	Codec string
}

// AutoSetClause defines a SQL expression always written into the SET clause.
// The SQLLiteral is emitted as raw SQL — codegen guarantees Column matches
// [A-Za-z_][A-Za-z0-9_]* and SQLLiteral is a single Postgres expression
// (validated at codegen time, not at runtime).
type AutoSetClause struct {
	// Column is the SQL column name that receives the expression.
	Column string
	// SQLLiteral is a raw SQL expression (e.g. "clock_timestamp()").
	SQLLiteral string
}

// EnumCodec maps a proto enum to/from a SQL text column. ToText is declared
// in aippatch.yaml; FromText is built by Validate from ToText.
type EnumCodec struct {
	// ProtoEnum is the fully-qualified proto enum name (e.g. "drill.v1.UserRole").
	// This field is metadata-only; it is not read by the runtime but is
	// useful for debugging and tooling.
	ProtoEnum string
	// ToText maps proto enum number → SQL text value (used by encode).
	ToText map[int32]string
	// FromText maps SQL text value → proto enum number (built by Validate from ToText).
	FromText map[string]int32
}

// Op carries a single PATCH invocation's runtime data.
type Op[T proto.Message] struct {
	// Message is the proto message whose field values are written. Must be non-nil.
	Message T
	// Mask lists the proto field names to include in the SET clause.
	Mask *fieldmaskpb.FieldMask
	// PKValue is the primary-key value for the WHERE clause. Must be a scalar
	// type accepted by pgx (e.g. uuid.UUID, int64, string).
	PKValue any
	// Where is an optional map of bound column names to additional WHERE
	// equality predicates. Each key must appear in Bindings. Values must be
	// pgx-bindable scalars.
	Where map[string]any
}

// DBTX is the minimal pgx interface aippatch needs. Satisfied by *pgxpool.Pool,
// *pgx.Conn, and pgx.Tx — Apply participates in a caller's transaction
// transparently when a tx is passed.
type DBTX interface {
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
}

// EmptyMaskPolicy controls behavior when Op.Mask has zero paths.
type EmptyMaskPolicy int

const (
	// ErrorOnEmpty is the v0 default; rejects empty mask with InvalidArgument.
	ErrorOnEmpty EmptyMaskPolicy = iota
	// UpdateAllWritable is reserved for v1; v0 returns Unimplemented.
	UpdateAllWritable
)
